@app.cell
def _(LIMIT_PER_SPLIT, MAX_NEW_TOKENS, SEED, SMOKE_TRAIN, SPLITS, WORK_DIR, mo, wc):
    # ───────────── data: download data/v2, verify checksums, enforce the split rule, build items ─────────────
    assert wc.DATA_VERSION == "v2" and MAX_NEW_TOKENS == wc.PART_MAX_NEW_TOKENS, (wc.DATA_VERSION, MAX_NEW_TOKENS)
    with mo.status.spinner(title=f"Downloading dataset {wc.DATA_VERSION}"):
        _sums_p = wc.hf_download(f"data/{wc.DATA_VERSION}/SHA256SUMS", WORK_DIR)
        assert _sums_p, f"data/{wc.DATA_VERSION}/SHA256SUMS missing in {wc.OUTPUTS_REPO}"
        _expected = dict(reversed(_l.split()) for _l in _sums_p.read_text().splitlines() if _l.strip())
        ROWS, DATA_SHA = {}, {}
        for _split in ("train", "validation", "test"):
            _p = wc.hf_download(wc.data_path(_split), WORK_DIR)
            assert _p, f"{wc.data_path(_split)} missing"
            DATA_SHA[_split] = wc.sha256_file(_p)
            assert DATA_SHA[_split] == _expected[f"{_split}.jsonl"], f"{_split}.jsonl checksum mismatch"
            ROWS[_split] = wc.load_jsonl(_p)
    _ov = wc.check_split_verbs(ROWS["train"], ROWS["validation"], ROWS["test"])
    print(f"verb overlap train&val={_ov['train&val']} train&test={_ov['train&test']} val&test={_ov['val&test']} (must all be [])")
    assert not (_ov["train&val"] or _ov["train&test"] or _ov["val&test"]), "split rule broken"
    assert tuple(_ov["test_verbs"]) == wc.TEST_VERBS, _ov["test_verbs"]
    assert all(r["messages"][0]["content"] == wc.PART_SYSTEM_PROMPT for _s in ROWS for r in ROWS[_s]), "system line differs from the app's"

    # training/validation-loss examples: (prompt in the phone's layout, reply + end-of-turn); loss on the reply only
    def _pairs(rows_):
        return [{"prompt": wc.phone_prompt(r_["messages"][0]["content"], r_["messages"][1]["content"]),
                 "completion": r_["messages"][2]["content"] + wc.PHONE_EOT, "verb": r_["meta"]["verb"], "part": r_["meta"]["part"]}
                for r_ in rows_]
    TRAIN_PAIRS, VAL_PAIRS = _pairs(ROWS["train"]), _pairs(ROWS["validation"])
    if SMOKE_TRAIN:
        _keep = set(wc.subset_md5(list(range(len(TRAIN_PAIRS))), SMOKE_TRAIN, salt=f"train{SEED}"))
        TRAIN_PAIRS = [p for i, p in enumerate(TRAIN_PAIRS) if i in _keep]
        VAL_PAIRS = VAL_PAIRS[:max(8, SMOKE_TRAIN // 3)]

    ITEMS_FORCED, ITEMS_CHAIN = {}, {}
    for _split in SPLITS:
        _chain = wc.chain_items_from_split(ROWS[_split], _split)
        _forced = wc.part_items_from_split(ROWS[_split], _split)
        if LIMIT_PER_SPLIT:  # deterministic, nested subset of exercises; forced items follow the kept exercises
            _keepx = set(wc.subset_md5([c["exercise_id"] for c in _chain], LIMIT_PER_SPLIT, salt=_split))
            _chain = [c for c in _chain if c["exercise_id"] in _keepx]
            _forced = [f for f in _forced if f"{_split}:{f['sentence_id']}#{f['variant']}" in _keepx]
        for _f in _forced:
            assert wc.part_prompt(_f["verb"], _f["part"], _f["done"], _f["avoid"]) == ROWS[_split][_f["idx"]]["messages"][1]["content"]
        ITEMS_CHAIN[_split], ITEMS_FORCED[_split] = _chain, _forced
    REFS = wc.known_valid([i for _s in ("validation", "test") for i in wc.part_items_from_split(ROWS[_s], _s)])
    print(f"checksums OK | train pairs {len(TRAIN_PAIRS)}, validation-loss pairs {len(VAL_PAIRS)} | eval",
          {k: len(v) for k, v in ITEMS_CHAIN.items()}, "exercises,", {k: len(v) for k, v in ITEMS_FORCED.items()},
          "questions | DATA_SHA", {k: v[:10] for k, v in DATA_SHA.items()})
    return DATA_SHA, ITEMS_CHAIN, ITEMS_FORCED, REFS, TRAIN_PAIRS, VAL_PAIRS


